CREATE TABLE IF NOT EXISTS owners (id BIGSERIAL PRIMARY KEY, username VARCHAR(80) UNIQUE NOT NULL, password VARCHAR(255) NOT NULL, name VARCHAR(120) NOT NULL, mobile_number VARCHAR(30), created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS organizations (id BIGSERIAL PRIMARY KEY, name VARCHAR(160) NOT NULL, address VARCHAR(255), owner_id BIGINT NOT NULL REFERENCES owners(id), created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS customers (id BIGSERIAL PRIMARY KEY, organization_id BIGINT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, name VARCHAR(160) NOT NULL, mobile_number VARCHAR(30) NOT NULL, father_name VARCHAR(160), address VARCHAR(255), created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS transactions (id BIGSERIAL PRIMARY KEY, customer_id BIGINT NOT NULL REFERENCES customers(id) ON DELETE CASCADE, transaction_date DATE NOT NULL, item VARCHAR(255) NOT NULL, quantity VARCHAR(30), rate NUMERIC(12,2), amount NUMERIC(12,2), balance NUMERIC(12,2) NOT NULL, created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP);
